import React, { Component } from "react";
import Loader from "react-loader-spinner";
import { Card, CardBody, CardHeader, Col, Row, Table, Button } from "reactstrap";
import { connect } from "react-redux";
import Pagination2 from "react-js-pagination";
// import Widget04 from './Widgets04';

import { interAffiliatePostOfficeSummary, interaffiliatePostOfficeSummaryCsv } from "../../../../actions/filesets";

import { FormattedMessage } from "react-intl";

// components
import PostingTable from "../../../../components/PostingTable";
import PostingTableHeader from "../../../../components/PostingTableHeader";

class PostOfficeSummary extends Component {
	constructor (props) {
		super(props);
		this.state = { activePage: 1 }; // sets activePage to the page from interaffiliate settlement Link tag or from pagination component or manually to what is entered in the url.
	}

	static getDerivedStateFromProps (props, state) {
		if (props.match.params.page !== state.activePage) {
			return {
				activePage : parseInt(props.match.params.page),
			};
		}

		// Return null if the state hasn't changed
		return null;
	}

	componentDidMount () {
		this.props.interAffiliatePostOfficeSummary(this.props.match.params.date, this.props.match.params.page - 1);
	}

	componentDidUpdate (prevProps) {
		if (this.props.match.params.page !== prevProps.match.params.page) {
			this.props.interAffiliatePostOfficeSummary(this.props.match.params.date, this.props.match.params.page);
		}

		if (this.props.selectedAffiliateCode !== prevProps.selectedAffiliateCode) {
			this.props.interAffiliatePostOfficeSummary(this.props.match.params.date, this.props.match.params.page - 1);
		}

		if (this.props.match.params.date !== prevProps.match.params.date) {
			this.props.interAffiliatePostOfficeSummary(this.props.match.params.date, this.props.match.params.page - 1);
		}
	}

	handlePageChange = (pageNumber) => {
		this.props.history.push(
			`/interAffiliate/settlement/postoffice/${this.props.match.params.date}/summary/${pageNumber}`,
		);
		this.setState({ activePage: pageNumber });
	};

	render () {
		const PostOfficeHeader = [
			"Tran Nr",
			"Terminal",
			"Date",
			"Time",
			"Location",
			"Card Acceptor Id Code",
			"Retrieval Reference Nr",
			"Message Type",
			"Tran Type",
			"Pan",
			"Card Acceptor Name Loc",
			"Auth Id Rsp",
			"Source Node Name",
			"Sink Node Name",
			"From Account Id",
			"System Trace Audit Nr",
			"Tran Amount Rsp",
			"Rran Cash Rsp",
			"Tran Currency Code",
			"Settle Currency Code",
			"Settle Amount Req",
			"Settle Amount Rsp",
			"Settle Cash Rsp",
			"Settle Amount Impact",
			"Switch Key",
		];

		return (
			<div className='animated fadeIn'>
				<Row>
					<Col lg={12}>
						<Card>
							<CardHeader>
								<strong>Post Office {this.props.match.params.date} Summary</strong>
								<div className='card-header-actions'>
									{this.props.interaffiliatePostOfficeSummary && (
										<article className='d-flex justify-content-between align-items-center w-100'>
											<Button
												type='button'
												className={"float-right mb-0 btn-sm mx-1"}
												onClick={() =>
													this.props.interaffiliatePostOfficeSummaryCsv(
														this.props.match.params.date,
													)}
												color={"success"}
												download={"" + 1 + ".csv"}
											>
												<span
													className={"d-flex px-2 justify-content-center align-items-center"}
												>
													<i className='fa fa-download' />&nbsp;
													{this.props.download_status && (
														<Loader
															type='ThreeDots'
															color='#FFF'
															height={30}
															width={30}
															style={{ textAlign: "center" }}
														/>
													)}
													{!this.props.download_status && (
														<FormattedMessage
															id='Download CSV'
															defaultMessage='Download CSV'
														/>
													)}
												</span>
											</Button>
										</article>
									)}
								</div>
							</CardHeader>

							<CardBody>
								{/* Handle loading */}
								{!this.props.interaffliatePostOfficeSummaryError &&
								!this.props.interaffiliatePostOfficeSummary && (
									<article className='d-flex justify-content-center align-items-center'>
										<div>
											<Loader type='ThreeDots' color='#00BFFF' height={100} width={100} />
										</div>
									</article>
								)}

								{!this.props.interaffiliatePostOfficeSummary &&
								this.props.interaffliatePostOfficeSummaryError && (
									<article className='d-flex justify-content-center align-items-center'>
										<p className='text-center text-danger'>
											<FormattedMessage
												id='Error unable to load entries.'
												defaultMessage='Error unable to load entries.'
											/>
										</p>
									</article>
								)}

								{/* Handle 404 Not found */}
								{this.props.interaffiliatePostOfficeSummary &&
								this.props.interaffiliatePostOfficeSummary.data &&
								this.props.interaffiliatePostOfficeSummary.data.content.length === 0 && (
									<article className='d-flex justify-content-center align-items-center'>
										<p className='text-center text-danger'>
											<FormattedMessage
												id='There are no fileset batches summary at the moment.'
												defaultMessage='There are no fileset batches summary at the moment.'
											/>
										</p>
									</article>
								)}

								{/* Handle display content */}
								{!this.props.interaffliatePostOfficeSummaryError &&
								this.props.interaffiliatePostOfficeSummary &&
								this.props.interaffiliatePostOfficeSummary.data &&
								this.props.interaffiliatePostOfficeSummary.data.content.length > 0 && (
									<Table hover bordered striped responsive size='sm' style={{ minWidth: "480%" }}>
										<thead>
											<PostingTableHeader headerType={"array"} headerPayload={PostOfficeHeader} />
										</thead>
										<tbody>
											<PostingTable
												tableName='interaffiliatePostOfficeSummary'
												dataRecords={
													this.props.interaffiliatePostOfficeSummary &&
													this.props.interaffiliatePostOfficeSummary.data ? (
														this.props.interaffiliatePostOfficeSummary.data.content
													) : (
														[]
													)
												}
											/>
										</tbody>
									</Table>
								)}

								{this.props.interaffiliatePostOfficeSummary && (
									<nav>
										<Pagination2
											activePage={this.state.activePage}
											itemsCountPerPage={this.props.interaffiliatePostOfficeSummary.size}
											totalItemsCount={
												(this.props.interaffiliatePostOfficeSummary &&
													this.props.interaffiliatePostOfficeSummary.data &&
													this.props.interaffiliatePostOfficeSummary.data.totalElements) ||
												null
											}
											pageRangeDisplayed={10}
											onChange={this.handlePageChange}
										/>
									</nav>
								)}
							</CardBody>
						</Card>
					</Col>
				</Row>
			</div>
		);
	}
}

const mapStateToProps = (state) => {
	return {
		interaffiliatePostOfficeSummary     : state.fileSets.interaffiliatePostOfficeSummary,
		interaffliatePostOfficeSummaryError : state.fileSets.interaffliatePostOfficeSummaryError,
		selectedAffiliateCode               : state.fileSets.selectedAffiliateCode,
		download_status                     : state.fileSets.download_status,
	};
};

export default connect(mapStateToProps, {
	interAffiliatePostOfficeSummary,
	interaffiliatePostOfficeSummaryCsv,
})(PostOfficeSummary);
